      sha256 "1c2df07c4c5b8f08e8ffae624f677404f65e29d5f1e17aa4f3d894601827feb8"
    end
  end

  def install
    bin.install "mosskeys"
    # Runs `mosskeys completions <shell>` at install time and links the
